{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C23"],
      "claim": "In healthy subjects, 5-hydroxyrofecoxib, a polar lactone-containing molecule, had oral bioavailability 14.9%, below the 20% threshold; its high transferability supports low F for the query's similarly polar, lactone-rich scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "9-Nitrocamptothecin, a lactone-containing natural product, showed very low absolute oral bioavailability in patients; poor absorption from polarity/dissolution issues is transferable to the query's multiple lactones and high TPSA.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "EM574, an oxygen-rich macrolide, had estimated human oral bioavailability of ~2%, far below 20%; high transferability supports low F for the query's polyoxygenated rigid structure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "HSYA, a highly polar glycosylated natural product, had low oral bioavailability in healthy volunteers; this directly supports low F for the query's very high polar surface area and H-bonding capacity.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Baicalin, a polar glucuronide, showed poor oral bioavailability in humans; its high TPSA/HBA burden parallels the query and supports low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "A complex oxygen-rich macrolide showed low absolute bioavailability in a healthy subject, reinforcing the pattern that rigid polyoxygenated natural products often fail to reach 20% oral F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Ixabepilone had absolute oral bioavailability of 41.3% in patients, above threshold; however, its much lower polarity and different permeability profile make this low-transferability evidence insufficient to override the high-transfer low-F analogues.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C10"],
      "claim": "Zidovudine showed 60-70% oral bioavailability, but as a small polar nucleoside with active transport and lower TPSA, it is not transferable to the query; this contradictory evidence has low weight.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C14"],
      "claim": "Artemisinin showed 61% absolute bioavailability in Thai patients, but artemisinin is far less polar than the query and other artemisinin records report low/poor F; moderate transferability and conflicting data limit its weight.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C18"],
      "claim": "Erythromycin base had ~32% absolute oral bioavailability in humans, above threshold, but as a lipophilic macrolide with lower TPSA and different permeability, its low transferability limits relevance.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
